/// <summary>
/// PaffH 29.08.25
/// </summary>
[ExtensionOf(formStr(AVAKBVCreateRequestTable))]
final class NDXAVAKBVCreateRequestTable_frm_Extension
{
    public NDXBVSearchContract nDXBVSearchContract;
    public NDXBVEMailRequestControlCenterFormI nDXBVEMailRequestControlCenterFormI;



}

Method.Source:
/// <summary>
/// PaffH 03.09.25
/// last modified: PaffH 01.10.25
/// get NDXBVSearchContract
/// </summary>
public void init()
{
    next init();

    Args args = this.args();
    if (args.caller() is FormRun)
    {
        FormRun fr = args.caller() as FormRun;

        nDXBVEMailRequestControlCenterFormI = NDXBVEMailRequestControlCenterForm::getNDXBVEMailRequestControlCenterFormI(fr);
        if (nDXBVEMailRequestControlCenterFormI)
        {
            nDXBVSearchContract = nDXBVEMailRequestControlCenterFormI.fillContract();
        }
        else if (formHasMethod(fr, Identifierstr(getNDXBVSearchContract)))
        {
            nDXBVSearchContract = fr.getNDXBVSearchContract();
            if (formHasMethod(fr, Identifierstr(getNDXBVEMailRequestControlCenterFormI)))
            {
                nDXBVEMailRequestControlCenterFormI = fr.getNDXBVEMailRequestControlCenterFormI();
            }
        }
    }
    if (nDXBVSearchContract)
    {
        frmKCS_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::find(nDXBVSearchContract.parmBuildingProjectId());
        frmKCS_KBVBuildingProjectID = frmKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID;

        KCS_KBVRequestTable.clear();
        KCS_KBVRequestTable.initValue();
        KCS_KBVRequestTable_ds.object(fieldNum(KCS_KBVRequestTable, KCS_KBVBuildingProjectID)).enabled(false);

        KCS_KBVRequestTable_DataAreaId.text(nDXBVSearchContract.parmDataAreaIdRequest());

        if (nDXBVSearchContract.parmDataAreaIdOrganisation() != curExt())
        {
            str info = 'Die BV E-Mail Anfrage, die dieser Anfrage zugrundeliegt, basiert auf einem andernen UK.\n';
            info += 'Aus diesem Grund muss der Anfrager und Kontakt für diese UK manuell bestimmt werden.';

            FormStaticTextBVEMailRequestFromDifferentCompanyInfo.text(info);

            NDXFormGroupBVEMailRequestFromDifferentCompany.visible(true);
            NDXCreateRequestAdditionalInfo nDXCreateRequestAdditionalInfo = NDXCreateRequestAdditionalInfo_ds.cursor();
            nDXCreateRequestAdditionalInfo.FieldString1 = "UK der BV E-Mail Anfrage";
            nDXCreateRequestAdditionalInfo.FieldString2 = nDXBVSearchContract.parmDataAreaIdOrganisation();
            nDXCreateRequestAdditionalInfo.insert();

            nDXCreateRequestAdditionalInfo.FieldString1 = "Kontakt";
            nDXCreateRequestAdditionalInfo.FieldString2 = nDXBVSearchContract.parmContactName();
            nDXCreateRequestAdditionalInfo.insert();
            if (nDXBVSearchContract.parmCustAccount())
            {
                nDXCreateRequestAdditionalInfo.FieldString1 = "Kunde";
                nDXCreateRequestAdditionalInfo.FieldString2 = nDXBVSearchContract.parmCustAccount();
                nDXCreateRequestAdditionalInfo.insert();
            }
            nDXCreateRequestAdditionalInfo.FieldString1 = "Party-Name";
            nDXCreateRequestAdditionalInfo.FieldString2 = nDXBVSearchContract.parmPartyName();
            nDXCreateRequestAdditionalInfo.insert();
        }

    }
}

/// <summary>
/// PaffH 01.10.25
/// </summary>
public void run()
{
    next run();

    if (nDXBVSearchContract)
    {
        ContactPerson contactPersonLocal = ContactPerson::findRecId(nDXBVSearchContract.parmRecIdContactPerson());
        KCS_KBVRequestTable.ContactPersonId = contactPersonLocal.ContactPersonId;
        KCS_KBVRequestTable.DirPartyId = contactPersonLocal.ContactForParty;
        FormStringControl fsc = this.design().controlName(formControlStr(AVAKBVCreateRequestTable, CustAccount));
        fsc.text(nDXBVSearchContract.parmCustAccount());
    }
}

/// <summary>
/// PaffH 06.10.25
/// </summary>
/// <param name = "_locArgs">Args</param>
/// <returns>insert KCS_KBVRequestTable ?</returns>
public boolean checkInsertKCS_KBVRequestTable(Args _locArgs)
{
    boolean retvalue = next checkInsertKCS_KBVRequestTable(_locArgs);
    if (nDXBVSearchContract)
    {
        retvalue = true;
    }
    return retvalue;
}

/// <summary>
/// PaffH 06.10.25
/// set ref to RequestTable
/// </summary>
/// <param name = "_KCS_KBVRequestTable">KCS_KBVRequestTable</param>
public void postInsertKCS_KBVRequestTable(KCS_KBVRequestTable _KCS_KBVRequestTable)
{
    next postInsertKCS_KBVRequestTable(_KCS_KBVRequestTable);

    if (nDXBVSearchContract)
    {
        nDXBVSearchContract.RequestCreated(_KCS_KBVRequestTable);

        if (nDXBVEMailRequestControlCenterFormI)
        {
            nDXBVEMailRequestControlCenterFormI.setRequestTable(nDXBVSearchContract);
        }
    }

}
